import math
prev_a=0.0
phase='rev'
tick=0
R2D=180/math.pi

def cvt(view,key):
    o=view.get('origin',[0,0]);out=[]
    for it in view.get(key,[]) or []:
        try:
            b,d=it[0],it[1]
            out.append((o[0]+d*math.cos(math.radians(b)),o[1]+d*math.sin(math.radians(b))))
        except Exception:
            pass
    return out

def control(obs):
    try:
        return _ctl(obs)
    except Exception as e:
        print('err',e)
        return (0.0,-0.5,-23)

def _ctl(obs):
    global prev_a,phase,tick
    tick+=1
    h=obs['hitch_deg'];rig=obs['rig'];R=rig['trailer_rear']
    if phase=='fwd':
        if abs(h)<8:
            phase='rev'
        else:
            return (-math.copysign(30,h),1.0,-23)
    if abs(h)>40:
        phase='fwd'
        print('recover fwd',round(h,1))
        return (-math.copysign(30,h),1.0,-23)
    back=math.radians(180-h)
    bx,by=math.cos(back),math.sin(back);lx,ly=-by,bx
    def tr(p):
        dx=p[0]-R[0];dy=p[1]-R[1]
        return (dx*bx+dy*by,dx*lx+dy*ly)
    views=obs.get('views') or {}
    walls=[];corners=[]
    for k,v in views.items():
        if not isinstance(v,dict):
            continue
        walls+=cvt(v,'walls')
        corners+=cvt(v,'target_corners')
    W=[tr(p) for p in walls]
    hw=rig.get('trailer_half_width',0.85)+0.3
    alpha=None
    slow=False
    if len(corners)>=2:
        C=[tr(p) for p in corners]
        cu=sum(c[0] for c in C)/len(C);cw=sum(c[1] for c in C)/len(C)
        au,aw=cu,cw
        if len(C)>=3:
            best=None
            for i in range(len(C)):
                for j in range(i+1,len(C)):
                    du=C[j][0]-C[i][0];dw=C[j][1]-C[i][1];L=math.hypot(du,dw)
                    if best is None or L>best[0]:
                        best=(L,du,dw)
            # use longest side-ish: pick pair with length between; approximate axis via longest edge not diagonal
            ds=[]
            for i in range(len(C)):
                for j in range(i+1,len(C)):
                    du=C[j][0]-C[i][0];dw=C[j][1]-C[i][1];ds.append((math.hypot(du,dw),du,dw))
            ds.sort()
            if len(ds)>=6:
                L,du,dw=ds[3]
            else:
                L,du,dw=ds[-1]
            if L>0.1:
                if du<0:
                    du,dw=-du,-dw
                au=cu+1.5*du/L;aw=cw+1.5*dw/L
        alpha=math.degrees(math.atan2(aw,max(au,0.3)))
        if math.hypot(cu,cw)<3:
            slow=True
    else:
        bestS=-1e9;afree=0
        for a in range(-60,61,3):
            ar=math.radians(a);c=math.cos(ar);s=math.sin(ar);free=9.0
            for u,w in W:
                p=u*c+w*s;q=-u*s+w*c
                if p>0 and abs(q)<hw and p<free:
                    free=p
            sc=free-0.015*abs(a)-0.01*abs(a-prev_a)
            if sc>bestS:
                bestS=sc;afree=a
        left=3.0;right=3.0
        for u,w in W:
            if -0.5<u<3.0:
                if w>0:
                    left=min(left,w)
                else:
                    right=min(right,-w)
        e=(left-right)/2.0
        ac=math.degrees(math.atan2(e,2.0))
        alpha=0.5*afree+ac
    alpha=max(-50,min(50,alpha))
    prev_a+=0.3*(alpha-prev_a)
    th=max(-30,min(30,-1.0*prev_a))
    t=math.radians(th)
    ff=math.degrees(math.atan(2.75*math.sin(t)/(2.6+1.05*math.cos(t))))
    steer=ff+1.5*(h-th)
    steer=max(-34,min(34,steer))
    sp=-0.6 if slow else -0.9
    if tick%20==0:
        print('t',round(obs['t'],1),'h',round(h,1),'a',round(prev_a,1),'th',round(th,1),'st',round(steer,1),'nc',len(corners),'nw',len(W))
    return (steer,sp,-23)

