import math
M={}
X=0.0;Y=0.0;PSI=0.0
phase='rev';fd=0.0;last_touch=None;idx=0;dwell=0.0;theta_f=0.0;stuck=0.0
SCAN=[64,160,64,-64,-160,-64]

def cl(a,lo,hi):
    return lo if a<lo else hi if a>hi else a

def control(obs):
    global X,Y,PSI,phase,fd,last_touch,idx,dwell,theta_f,stuck,M
    dt=obs.get('dt',0.1) or 0.1
    mo=obs['motion']; v=mo.get('v_mps',0.0); st=obs.get('steer_deg',0.0)
    t=obs.get('t',0.0)
    PSI+=v*math.tan(math.radians(st))/2.5*dt
    X+=v*math.cos(PSI)*dt; Y+=v*math.sin(PSI)*dt
    c=math.cos(PSI); s=math.sin(PSI)
    views=obs.get('views') or {}
    for name,vw in views.items():
        if not vw: continue
        ox,oy=vw.get('origin',[0,0])
        for p in vw.get('walls',[]) or []:
            b,d=p[0],p[1]
            px=ox+d*math.cos(math.radians(b)); py=oy+d*math.sin(math.radians(b))
            wx=X+c*px-s*py; wy=Y+s*px+c*py
            M[(round(wx*4),round(wy*4))]=(wx,wy,t)
    M={k:q for k,q in M.items() if t-q[2]<10}
    rig=obs['rig']; rx,ry=rig['trailer_rear']; th=rig.get('trailer_heading_deg',0.0)
    h=obs.get('hitch_deg',0.0)
    ang=math.radians(180+th); ca=math.cos(ang); sa=math.sin(ang)
    P=[]
    for (wx,wy,tt) in M.values():
        dx=wx-X; dy=wy-Y
        px=c*dx+s*dy; py=-s*dx+c*dy
        ex=px-rx; ey=py-ry
        u=ex*ca+ey*sa; lat=-(-ex*sa+ey*ca)
        P.append((u,lat))
    def freeat(deg):
        r=math.radians(deg); cr=math.cos(r); sr=math.sin(r); f=15.0
        for (u,lat) in P:
            sp=u*cr+lat*sr
            if sp<=0 or sp>=f: continue
            pp=-u*sr+lat*cr
            if abs(pp)<1.5: f=sp
        return f
    cands=list(range(-60,61,3))
    frees=[freeat(a) for a in cands]
    mx=max(frees)
    good=[(f>=mx-0.5 or f>=12) for f in frees]
    best=(0,0);i=0
    while i<len(cands):
        if good[i]:
            j=i
            while j+1<len(cands) and good[j+1]: j+=1
            if j-i>best[1]-best[0] or (best==(0,0) and not good[0]): best=(i,j)
            i=j+1
        else: i+=1
    if not P: theta=0.0
    else: theta=(cands[best[0]]+cands[best[1]])/2.0
    cll=3.0; clr=3.0
    for (u,lat) in P:
        if -3<u<2:
            if lat>0: cll=min(cll,lat)
            else: clr=min(clr,-lat)
    if min(cll,clr)<2.5: theta+=cl(6*(cll-clr),-12,12)
    tg=obs.get('target') or {}
    if tg.get('in_sight') and tg.get('dist_m') is not None and tg['dist_m']<15:
        b=math.radians(tg['bearing_deg']); d=tg['dist_m']
        tx=0.75+d*math.cos(b)-rx; ty=d*math.sin(b)-ry
        u=tx*ca+ty*sa; lat=-(-tx*sa+ty*ca)
        at=math.degrees(math.atan2(lat,u))
        if abs(at)<60: theta=0.4*theta+0.6*at
    theta_f+=0.3*(theta-theta_f)
    fc=freeat(theta_f)
    touches=obs['counters'].get('touches',0)
    status=obs.get('status','')
    if last_touch is None: last_touch=touches
    newtouch=touches>last_touch
    last_touch=touches
    if phase=='rev':
        if newtouch or status=='JACKKNIFED' or abs(h)>45 or (P and fc<0.8):
            phase='fwd'; fd=0.0; stuck=0.0
            try: wake('recovery fwd: touch=%s status=%s h=%.0f free=%.1f'%(newtouch,status,h,fc))
            except Exception: pass
    else:
        fd+=abs(v)*dt
        if mo.get('hold_s',0)<=0 and abs(v)<0.05: stuck+=dt
        else: stuck=0.0
        if newtouch or stuck>3 or (fd>2.0 and abs(h)<10) or fd>4.0:
            phase='rev'
    # head
    hd=obs.get('head') or {}
    g=hd.get('gaze_deg',0)
    tgt=SCAN[idx%len(SCAN)]
    if hd.get('settled') and abs(g-tgt)<3:
        dwell+=dt
        if dwell>=0.3:
            idx+=1; dwell=0.0
    look=SCAN[idx%len(SCAN)]
    if phase=='fwd':
        steer=cl(-0.6*h,-25,25)
        return (steer,0.8,look)
    hd_=cl(1.0*theta_f,-30,30)
    steer=cl(2.0*(h-hd_),-45,45)
    spd=-0.6 if fc>4 else -0.35
    rem=(obs.get('progress') or {}).get('remaining',99)
    if rem is not None and rem<4: spd=max(spd,-0.4)
    if int(t*10)%30==0:
        print('t%.0f h%.0f th%.0f hd%.0f fc%.1f L%.1f R%.1f rem%s'%(t,h,theta_f,hd_,fc,cll,clr,rem))
    return (steer,spd,look)

