import math
X=0.0;Y=0.0;PSI=0.0
pts={}
last_t=None
mode='rev'
TGT=None
lastwake=-99
phi_hold=None
lastprint=-99
def W(m):
    try:
        wake(m)
    except Exception:
        pass
def wrap(a):
    while a>180: a-=360
    while a<-180: a+=360
    return a
def clamp(v,a,b):
    return max(a,min(b,v))
def to_world(px,py):
    c=math.cos(PSI);s=math.sin(PSI)
    return X+c*px-s*py, Y+s*px+c*py
def to_veh(wx,wy):
    dx=wx-X;dy=wy-Y;c=math.cos(PSI);s=math.sin(PSI)
    return c*dx+s*dy, -s*dx+c*dy
def rectdist(px,py,cx,cy,hd,hl_back,hl_front,hw):
    c=math.cos(math.radians(hd));s=math.sin(math.radians(hd))
    dx=px-cx;dy=py-cy
    a=c*dx+s*dy;l=-s*dx+c*dy
    ea=max(-hl_back-a,0,a-hl_front);el=max(abs(l)-hw,0)
    return math.hypot(ea,el)
def control(obs):
    global X,Y,PSI,last_t,mode,TGT,lastwake,phi_hold,lastprint
    t=obs['t']
    m=obs['motion'];v=m['v_mps'];st=obs['steer_deg']
    if last_t is not None:
        d=t-last_t
        X+=v*math.cos(PSI)*d;Y+=v*math.sin(PSI)*d
        PSI+=v/1.25*math.tan(math.radians(st))*d
    last_t=t
    for k,vw in (obs.get('views') or {}).items():
        try:
            ox,oy=vw['origin']
            for b,dd in vw.get('walls',[]):
                if dd>8: continue
                px=ox+dd*math.cos(math.radians(b));py=oy+dd*math.sin(math.radians(b))
                wx,wy=to_world(px,py)
                pts[(round(wx*10),round(wy*10))]=(wx,wy)
        except Exception:
            pass
    tg=obs.get('target') or {}
    if tg.get('in_sight') and tg.get('bearing_deg') is not None and tg.get('dist_m') is not None:
        b=math.radians(tg['bearing_deg']);dd=tg['dist_m']
        wx,wy=to_world(0.1+dd*math.cos(b),dd*math.sin(b))
        if TGT is None: TGT=(wx,wy)
        else: TGT=(0.8*TGT[0]+0.2*wx,0.8*TGT[1]+0.2*wy)
    rig=obs['rig'];hitch=obs['hitch_deg']
    rear=rig['trailer_rear'];th=rig['trailer_heading_deg']
    look=165 if int(t/4)%2==0 else -165
    if mode=='rev' and abs(hitch)>40:
        mode='fwd';W('hitch %.0f, pulling forward'%hitch)
    if mode=='fwd':
        if abs(hitch)<8:
            mode='rev'
        else:
            return (clamp(-1.2*hitch,-45,45),0.6,look)
    Rw=to_world(rear[0],rear[1])
    thr=math.radians(th)
    Ax=rear[0]+0.45*math.cos(thr);Ay=rear[1]+0.45*math.sin(thr)
