import math
st={'alpha':0.0,'mode':'rev','n':0,'woke':0}
CAM=-41.0
def wrap(a):
    while a>180: a-=360
    while a<-180: a+=360
    return a
def clamp(x,a,b):
    return max(a,min(b,x))
def control(obs):
    try:
        return _c(obs)
    except Exception as e:
        print('err',e)
        return (0.0,0.0,CAM)
def _c(obs):
    st['n']+=1
    hitch=obs['hitch_deg']
    rig=obs['rig']
    th=rig['trailer_heading_deg']
    R=rig['trailer_rear']
    hw=rig['trailer_half_width']
    back=th+180.0
    if st['mode']=='fwd':
        if abs(hitch)<8:
            st['mode']='rev'
        else:
            return (0.0,1.5,CAM)
    if abs(hitch)>48:
        st['mode']='fwd'
        print('fwd recover hitch',round(hitch,1))
        return (0.0,1.5,CAM)
    views=obs.get('views') or {}
    cam=views.get('camera')
    stop=False
    if cam:
        ox,oy=cam['origin']
        pts=[]
        for b,d in cam.get('walls',[]):
            px=ox+d*math.cos(math.radians(b)); py=oy+d*math.sin(math.radians(b))
            dx=px-R[0]; dy=py-R[1]
            a=wrap(math.degrees(math.atan2(dy,dx))-back)
            r=math.hypot(dx,dy)
            pts.append((a,r))
        best=None;bs=-1e9
        for k in range(-12,13):
            al=k*5.0
            free=15.0
            for a,r in pts:
                da=math.radians(wrap(a-al))
                s=r*math.cos(da); p=abs(r*math.sin(da))
                if s>0 and p<hw+0.7:
                    free=min(free,s)
            sc=free-0.04*abs(al)-0.02*abs(al-st['alpha'])
            if sc>bs: bs=sc;best=al
        # centering near rear
        lmin=9.0;rmin=9.0
        for a,r in pts:
            s=r*math.cos(math.radians(a)); lat=r*math.sin(math.radians(a))
            if -1.0<s<5.0:
                if lat>0: lmin=min(lmin,lat)
                else: rmin=min(rmin,-lat)
            if 0<s<1.2 and abs(lat)<hw+0.15: stop=True
        cen=0.0
        if lmin<9 and rmin<9:
            cen=clamp(4.0*(lmin-rmin),-15,15)
        tgt=None
        tc=cam.get('target_corners') or []
        if len(tc)>=2:
            sx=sy=0.0
            for b,d in tc:
                sx+=ox+d*math.cos(math.radians(b)); sy+=oy+d*math.sin(math.radians(b))
            sx/=len(tc); sy/=len(tc)
            tgt=wrap(math.degrees(math.atan2(sy-R[1],sx-R[0]))-back)
        if tgt is not None and len(tc)>=3:
            al=tgt
        else:
            al=best+0.5*cen
        st['alpha']=0.7*st['alpha']+0.3*al
    hd=clamp(0.8*st['alpha'],-22,22)
    steer=clamp(1.6*(hitch-hd),-40,40)
    sp=-1.0
    if stop:
        sp=0.0
        if not st['woke']:
            st['woke']=1; obs and None
            try: wake('wall close behind trailer, stopped')
            except Exception: pass
    if st['n']%20==0:
        print('t',round(obs['t'],1),'h',round(hitch,1),'al',round(st['alpha'],1),'hd',round(hd,1),'st',round(steer,1))
    return (steer,sp,CAM)

