    S['X']+=v*math.cos(S['P'])*dt;S['Y']+=v*math.sin(S['P'])*dt;S['P']+=v*math.tan(sd)/3.9*dt
    rig=obs['rig'];vf=rig.get('vehicle_front',5.2);vw=rig.get('vehicle_half_width',1.275);hw=rig['trailer_half_width']
    views=obs.get('views') or {}
    fnear=9.0
    for name in ('direct','periphery','left_mirror','right_mirror','camera'):
        vv=views.get(name)
        if not isinstance(vv,dict): continue
        ox,oy=vv['origin']
        for b,d in vv.get('walls',[]) or []:
            bx=ox+d*math.cos(math.radians(b));by=oy+d*math.sin(math.radians(b))
            if name in ('direct','periphery') and bx>vf-1.5:
                ex=max(bx-vf,0);ey=max(abs(by)-vw,0)
                fnear=min(fnear,math.hypot(ex,ey))
            if d>12 or name=='periphery': continue
            wx,wy=b2w(bx,by)
            S['map'][(int(round(wx/0.3)),int(round(wy/0.3)))]=(wx,wy,t)
        for b,d in vv.get('target_corners',[]) or []:
            if d>30: continue
            wx,wy=b2w(ox+d*math.cos(math.radians(b)),oy+d*math.sin(math.radians(b)))
            for c in S['bay']:
                if math.hypot(c[0]-wx,c[1]-wy)<1.5:
                    c[0]=0.8*c[0]+0.2*wx;c[1]=0.8*c[1]+0.2*wy;c[2]+=1;break
            else:
                if len(S['bay'])<6: S['bay'].append([wx,wy,1])
    if n%30==0:
        S['map']={k:vv for k,vv in S['map'].items() if t-vv[2]<8}
    walls=[(vv[0],vv[1]) for vv in S['map'].values() if t-vv[2]<7]
    hitch=obs['hitch_deg']
    psi=math.degrees(S['P'])
    if S['mode'] in ('A','B','C'):
        S['fd']+=abs(v)*dt
        lk=20.0 if n%20<10 else -25.0
        if n%10==0: print('F',S['mode'],'t',round(t,1),'d',round(S['fd'],1),'h',round(hitch,1),'psi',round(psi,1),'Y',round(S['Y'],2),'fn',round(fnear,2))
        if fnear<0.6 and S['fd']>0.3:
            print('front close, abort fwd')
            S['mode']='rev';return (0.0,0.0,CAM)
        if S['mode']=='A':
            if psi>=14.0: S['mode']='B'
            return (14.0,1.0,lk)
        if S['mode']=='B':
            if psi<=3.0: S['mode']='C'
            return (-14.0,1.0,lk)
        stc=clamp(-3.0*psi,-14,14)
        if (abs(psi)<1.5 and abs(hitch)<6) or S['fd']>22:
            S['mode']='rev';print('fwd done h',round(hitch,1),'psi',round(psi,1),'Y',round(S['Y'],2))
            return (stc,0.0,CAM)
        return (stc,0.9,lk)
    lk=look(n)
    if S['mode']=='fwd':
        if abs(hitch)<12: S['mode']='rev'
        else: return (0.0,1.0,RM)
    if abs(hitch)>40:
        S['mode']='fwd';w('hitch %.0f, pulling forward'%hitch)
        return (0.0,1.0,RM)
    if S['hd'] is None or n%10==1:
        (sc,hd,mc,free),bay=plan(obs,walls,vf,vw,hw)
        S['hd']=hd;S['plan']=(mc,free,sc)
        if n%20==1:
            print('t',round(t,1),'h',round(hitch,1),'hd',hd,'mc',round(mc,2),'fr',round(free,1),'bay',None if not bay else (round(bay[0],1),round(bay[1],1)),'rem',round(obs['progress']['remaining'],1),'nw',len(walls))
    cc=clr(S['X'],S['Y'],S['P'],S['P']-math.radians(hitch),walls,vf,vw,hw)
    steer=clamp(1.5*(hitch-S['hd']),-40,40)
    sp=-0.7
    if cc<0.5 or S['plan'][0]<0.5: sp=-0.45
    if cc<0.15 or S['plan'][0]<0.2:
        sp=0.0
        if abs(v)<0.05: w('blocked: clr now %.2f, plan %.2f, hitch %.1f'%(cc,S['plan'][0],hitch))
    return (steer,sp,lk)
